// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.persona.jit/** * NOUS — JIT Context Payload (Module 15 v3.0 — Step 15.2). * * The assembled context payload that the [JitContextFetcher] produces during * the 300ms wake-word STT gap. This payload is injected into the LLM prompt * so NOUS has "omniscient awareness" of the device state without any * background polling. * * ## What's in the payload * *  - **Battery** — current %, charging state, low-battery flag. *  - **Media** — currently playing track + artist + genre (for mood detection). *  - **Call log** — today's calls + missed calls from frequent contacts. *  - **App usage** — top app used in the last hour (context: "you were just *    on YouTube"). *  - **Interaction gap** — time since last NOUS interaction (for neglect trigger). *  - **Gossip triggers** — evaluated triggers that NOUS should mention *    (battery hungry, music mood, social check, user neglect). * * ## Privacy * * All data stays on-device. Nothing is synced to cloud. The payload is * ephemeral — used for one LLM call then discarded. Call log + app usage * require special permissions (READ_CALL_LOG, PACKAGE_USAGE_STATS) which * the user grants explicitly in Settings. * * @see <a href="docs/strategy/module-15-digital-soul-strategy.md">§4 JIT Ambient Observer</a> */data class JitContextPayload(    /** Battery state at the time of the wake word. */    val battery: BatteryInfo? = null,    /** Currently playing media (null if nothing playing). */    val media: MediaInfo? = null,    /** Today's call log summary (null if permission not granted). */    val callLog: CallLogInfo? = null,    /** Top app used in the last hour (null if permission not granted). */    val appUsage: AppUsageInfo? = null,    /** Time since last NOUS interaction (null = first interaction). */    val interactionGapMs: Long? = null,    /** Evaluated gossip triggers (what NOUS should mention). */    val gossipTriggers: List<GossipTriggerResult> = emptyList(),) {    /**     * Build a human-readable context summary for the LLM prompt.     *     * Example:     * ```     * [CONTEXT] Battery: 45% (not charging). Music: "Bohemian Rhapsody" by     * Queen (rock). Last interaction: 14 hours ago. No calls from Mom today.     * ```     */    fun toPromptString(): String {        val parts = mutableListOf<String>()        battery?.let { parts.add("Battery: ${it.level}% (${if (it.isCharging) "charging" else "not charging"})") }        media?.let { parts.add("Music: \"${it.track}\" by ${it.artist} (${it.genre})") }        appUsage?.let { parts.add("Last app used: ${it.appName}") }        interactionGapMs?.let {            val hours = it / 3_600_000            if (hours > 0) parts.add("Last interaction: ${hours}h ago")        }        callLog?.let {            if (it.missedFromFrequent.isNotEmpty()) {                parts.add("Missed calls from: ${it.missedFromFrequent.joinToString()}")            }        }        if (parts.isEmpty()) return ""        return "[CONTEXT] ${parts.joinToString(". ")}."    }}// ──────────────────────────────────────────────────────────────────────────/** Battery state snapshot. */data class BatteryInfo(    val level: Int,            // 0-100    val isCharging: Boolean,    val isLow: Boolean,        // < 15%) {    init {        require(level in 0..100) { "level must be in [0,100], got $level" }    }}/** Currently playing media. */data class MediaInfo(    val track: String,    val artist: String,    val genre: String,         // "rock", "pop", "sad", "dance", "unknown"    val packageName: String,   // which app is playing (Spotify, YouTube Music, etc.))/** Call log summary for today. */data class CallLogInfo(    /** Total calls today (incoming + outgoing + missed). */    val totalToday: Int,    /** Missed calls today. */    val missedToday: Int,    /** Frequent contacts who haven't called today (by display name). */    val missedFromFrequent: List<String>,)/** Top app used in the last hour. */data class AppUsageInfo(    val packageName: String,    val appName: String,    /** Time spent in foreground (seconds) in the last hour. */    val foregroundSeconds: Long,)// ──────────────────────────────────────────────────────────────────────────/** * A gossip trigger that fired — something NOUS should mention. * * Per strategy §4 "Gossip Triggers": *  - Music/Mood Intelligence (sad → empathy, dance → hype) *  - User Neglect (> 12 hours since last interaction) *  - Battery Hunger (< 15%) *  - Social Check (frequent contact didn't call today) * * Each trigger has a [GossipTriggerType] + a persona-specific message hint * that the LLM uses to craft a natural response. */data class GossipTriggerResult(    val type: GossipTriggerType,    /** A hint for the LLM (e.g., "The user's battery is at 5% — suggest charging"). */    val hint: String,    /** Priority (1=low, 10=critical). Higher = mention first. */    val priority: Int,)/** Types of gossip triggers (per strategy §4). */enum class GossipTriggerType(val displayLabel: String) {    /** Battery < 15% — suggest charging. */    BATTERY_HUNGRY("Battery Hungry"),    /** Music genre detected — react to mood (sad → empathy, dance → hype). */    MUSIC_MOOD("Music Mood"),    /** User hasn't interacted with NOUS in > 12 hours. */    USER_NEGLECT("User Neglect"),    /** A frequent contact didn't call today — check in. */    SOCIAL_CHECK("Social Check"),}